def wpos(node, f):
    return node.worldTransformAtTime(hou.frameToTime(f)).extractTranslates()

def wmat(node, f):
    return node.worldTransformAtTime(hou.frameToTime(f))

def project(camname, P, f):
    cam = hou.node('/obj/' + camname)
    t = hou.frameToTime(f)
    M = cam.worldTransformAtTime(t).inverted()
    p = hou.Vector3(P) * M
    if p[2] >= 0:
        return None
    foc = cam.parm('focal').evalAtTime(t)
    ap = cam.parm('aperture').evalAtTime(t)
    rx = cam.parm('resx').evalAtTime(t); ry = cam.parm('resy').evalAtTime(t)
    asp = cam.parm('aspect').evalAtTime(t)
    x = (foc / ap) * p[0] / (-p[2])
    y = (foc / ap) * p[1] / (-p[2]) * (rx / (ry / asp)) if False else (foc / ap) * p[1] / (-p[2]) * rx * asp / ry
    return (x + 0.5, y + 0.5, -p[2])

def inframe(camname, P, f, margin=0.0):
    r = project(camname, P, f)
    if r is None:
        return False
    return margin <= r[0] <= 1 - margin and margin <= r[1] <= 1 - margin

